import{_ as i,o as a,c as n,a4 as l}from"./chunks/framework.B-wJupoK.js";const p="/assets/image-20250806140827228._9iuMKZv.png",h="/assets/image-20250806140844041.1GT8bre0.png",e="/assets/image-20250806140732186.CdWfOM-R.png",k="/assets/image-20250622200325374.BLr7GNE1.png",t="/assets/image-20250804212748706.Do1Id4N3.png",b=JSON.parse("{\"title\":\"HarmonyOS 读取系统相册图片并预览\",\"description\":\"\",\"frontmatter\":{},\"headers\":[],\"relativePath\":\"鸿蒙开发技巧/HarmonyOS 读取系统相册图片并预览/HarmonyOS 读取系统相册图片并预览.md\",\"filePath\":\"鸿蒙开发技巧/HarmonyOS 读取系统相册图片并预览/HarmonyOS 读取系统相册图片并预览.md\",\"lastUpdated\":1756109794000,\"__rawMarkdown\":\"# HarmonyOS 读取系统相册图片并预览\\n\\n## 概述\\n\\n本文将详细介绍如何在 HarmonyOS 应用中实现读取用户相册图片并进行预览的功能。通过使用 HarmonyOS 提供的媒体库 API 和权限管理机制，我们可以安全、高效地访问用户的图片资源。\\n\\n## 效果图\\n\\n![image-20250806140827228](assets/image-20250806140827228.png)\\n\\n---\\n\\n![image-20250806140844041](assets/image-20250806140844041.png)\\n\\n---\\n\\n\\n\\n\\n\\n![image-20250806140732186](assets/image-20250806140732186.png)\\n\\n\\n\\n## 核心 API 介绍\\n\\n### 1. PhotoAccessHelper API\\n\\n`PhotoAccessHelper` 是 HarmonyOS 提供的媒体库访问助手，用于管理和访问用户的图片、视频等媒体资源。\\n\\n```typescript\\nimport { photoAccessHelper } from '@kit.MediaLibraryKit';\\n\\n// 获取 PhotoAccessHelper 实例\\nthis.phAccessHelper = photoAccessHelper.getPhotoAccessHelper(this.context);\\n```\\n\\n**主要功能：**\\n- 获取媒体资源列表\\n- 支持条件查询和排序\\n- 获取媒体文件的缩略图\\n- 访问媒体文件的元数据\\n\\n### 2. 权限管理 API\\n\\n访问用户相册需要申请 `ohos.permission.READ_IMAGEVIDEO` 权限。\\n\\n```typescript\\nimport { abilityAccessCtrl, PermissionRequestResult } from '@kit.AbilityKit';\\n\\n// 检查和请求权限\\nconst atManager = abilityAccessCtrl.createAtManager();\\nconst permission = 'ohos.permission.READ_IMAGEVIDEO';\\n```\\n\\n### 3. 数据查询 API\\n\\n使用 `DataSharePredicates` 进行数据查询和排序。\\n\\n```typescript\\nimport { dataSharePredicates } from '@kit.ArkData';\\n\\n// 创建查询条件\\nconst fetchOptions: photoAccessHelper.FetchOptions = {\\n  fetchColumns: [\\n    photoAccessHelper.PhotoKeys.URI,\\n    photoAccessHelper.PhotoKeys.DISPLAY_NAME,\\n    photoAccessHelper.PhotoKeys.SIZE,\\n    photoAccessHelper.PhotoKeys.DATE_ADDED\\n  ],\\n  predicates: new dataSharePredicates.DataSharePredicates()\\n};\\n```\\n\\n### 4. 文件系统 API\\n\\n获取文件详细信息，如文件大小。\\n\\n```typescript\\nimport { fileIo as fs } from '@kit.CoreFileKit';\\n\\n// 获取文件统计信息\\nconst file = fs.openSync(asset.uri, fs.OpenMode.READ_ONLY);\\nconst stat = await fs.stat(file.fd);\\nconst fileSize = stat.size;\\n```\\n\\n## 核心组件介绍\\n\\n### 1. 数据模型组件\\n\\n#### ImageItem 类\\n图片项数据模型，使用 V2 状态管理。\\n\\n```typescript\\n@ObservedV2\\nclass ImageItem {\\n  @Trace id: string = '';           // 图片唯一标识\\n  @Trace name: string = '';         // 图片名称\\n  @Trace size: number = 0;          // 文件大小\\n  @Trace createTime: string = '';   // 创建时间\\n  @Trace thumbnail: image.PixelMap | null = null;  // 缩略图\\n  @Trace photoAsset: photoAccessHelper.PhotoAsset | null = null;  // 原始资源\\n}\\n```\\n\\n#### GalleryModel 类\\n图片浏览页面的状态管理模型。\\n\\n```typescript\\n@ObservedV2\\nclass GalleryModel {\\n  @Trace images: ImageItem[] = [];          // 所有图片列表\\n  @Trace filteredImages: ImageItem[] = [];  // 过滤后的图片列表\\n  @Trace isLoading: boolean = false;       // 加载状态\\n  @Trace hasPermission: boolean = false;   // 权限状态\\n  @Trace isSearchMode: boolean = false;    // 搜索模式\\n}\\n```\\n\\n### 2. UI 组件\\n\\n#### 主页面组件\\n使用 V2 组件架构，支持响应式状态管理。\\n\\n```typescript\\n@Entry\\n@ComponentV2\\nexport struct Page01 {\\n  @Local localModel: GalleryModel = new GalleryModel();\\n  private context: common.UIAbilityContext = getContext(this) as common.UIAbilityContext;\\n  private phAccessHelper: photoAccessHelper.PhotoAccessHelper | null = null;\\n}\\n```\\n\\n#### 图片网格项组件\\n自定义 Builder 函数，用于构建单个图片项的 UI。\\n\\n```typescript\\n@Builder\\nbuildImageItem(image: ImageItem) {\\n  Stack({ alignContent: Alignment.TopEnd }) {\\n    Column() {\\n      // 图片缩略图显示\\n      if (image.thumbnail) {\\n        Image(image.thumbnail)\\n          .width('100%')\\n          .height(120)\\n          .objectFit(ImageFit.Cover)\\n      } else {\\n        // 默认占位图\\n        Image($r('app.media.startIcon'))\\n          .backgroundColor('#F0F0F0')\\n      }\\n      \\n      // 图片信息显示\\n      Column() {\\n        Text(image.name)  // 图片名称\\n        Row() {\\n          Text(this.formatDateTime(image.createTime))  // 创建时间\\n          Text(this.formatFileSize(image.size))        // 文件大小\\n        }\\n      }\\n    }\\n  }\\n}\\n```\\n\\n## 主要实现步骤\\n\\n### 步骤 1：声明权限\\n\\n在**modules.json5**中声明权限\\n\\n```json\\nrequestPermissions: [\\n    {\\n        name: \\\"ohos.permission.READ_IMAGEVIDEO\\\",\\n        reason: \\\"$string:EntryAbility_label\\\",\\n        usedScene: { abilities: [] },\\n    },\\n],\\n```\\n\\n\\n\\n### 步骤 2：权限申请\\n\\n在访问用户相册之前，必须先申请相应的权限。\\n\\n```typescript\\nprivate async requestPermission(): Promise<boolean> {\\n  try {\\n    const atManager = abilityAccessCtrl.createAtManager();\\n    const permission = 'ohos.permission.READ_IMAGEVIDEO';\\n\\n    // 检查权限状态\\n    const grantStatus = await atManager.checkAccessToken(\\n      this.context.applicationInfo.accessTokenId, \\n      permission\\n    );\\n\\n    if (grantStatus === abilityAccessCtrl.GrantStatus.PERMISSION_GRANTED) {\\n      return true;\\n    }\\n\\n    // 请求权限\\n    const requestResult: PermissionRequestResult = \\n      await atManager.requestPermissionsFromUser(this.context, [permission]);\\n\\n    return requestResult.authResults[0] === abilityAccessCtrl.GrantStatus.PERMISSION_GRANTED;\\n  } catch (error) {\\n    console.error('权限请求失败:', error);\\n    return false;\\n  }\\n}\\n```\\n\\n### 步骤 3：初始化 PhotoAccessHelper\\n\\n获取权限后，初始化媒体库访问助手。\\n\\n```typescript\\nprivate async initializeGallery(): Promise<void> {\\n  try {\\n    this.localModel.isLoading = true;\\n\\n    // 请求权限\\n    const hasPermission = await this.requestPermission();\\n    if (!hasPermission) {\\n      this.localModel.hasPermission = false;\\n      return;\\n    }\\n\\n    this.localModel.hasPermission = true;\\n\\n    // 初始化 PhotoAccessHelper\\n    this.phAccessHelper = photoAccessHelper.getPhotoAccessHelper(this.context);\\n\\n    // 加载图片\\n    await this.loadImagesFromAlbum();\\n  } catch (error) {\\n    console.error('初始化图库失败:', error);\\n  } finally {\\n    this.localModel.isLoading = false;\\n  }\\n}\\n```\\n\\n### 步骤 4：查询图片资源\\n\\n配置查询选项，获取用户相册中的图片。\\n\\n```typescript\\nprivate async loadImagesFromAlbum(): Promise<void> {\\n  if (!this.phAccessHelper) {\\n    console.error('PhotoAccessHelper未初始化');\\n    return;\\n  }\\n\\n  try {\\n    // 创建获取选项\\n    const fetchOptions: photoAccessHelper.FetchOptions = {\\n      fetchColumns: [\\n        photoAccessHelper.PhotoKeys.URI,\\n        photoAccessHelper.PhotoKeys.DISPLAY_NAME,\\n        photoAccessHelper.PhotoKeys.SIZE,\\n        photoAccessHelper.PhotoKeys.DATE_ADDED\\n      ],\\n      predicates: new dataSharePredicates.DataSharePredicates()\\n    };\\n\\n    // 按时间倒序排列\\n    fetchOptions.predicates?.orderByDesc(photoAccessHelper.PhotoKeys.DATE_ADDED);\\n\\n    // 获取图片资源\\n    const fetchResult = await this.phAccessHelper.getAssets(fetchOptions);\\n    const photoAssets = await fetchResult.getAllObjects();\\n\\n    // 处理图片数据...\\n  } catch (error) {\\n    console.error('加载相册图片失败:', error);\\n  }\\n}\\n```\\n\\n### 步骤 5：处理图片数据\\n\\n将获取的图片资源转换为应用内的数据模型。\\n\\n```typescript\\n// 转换为 ImageItem 数组\\nconst imageItems: ImageItem[] = [];\\n\\nfor (let i = 0; i < Math.min(photoAssets.length, 50); i++) {\\n  const asset = photoAssets[i];\\n  try {\\n    // 获取缩略图\\n    const thumbnail = await asset.getThumbnail({ width: 300, height: 300 });\\n\\n    // 获取文件大小\\n    let fileSize = 0;\\n    try {\\n      const file = fs.openSync(asset.uri, fs.OpenMode.READ_ONLY);\\n      const stat = await fs.stat(file.fd);\\n      fileSize = stat.size;\\n      fs.closeSync(file.fd);\\n    } catch (sizeError) {\\n      console.error(`获取文件大小失败:`, sizeError);\\n      fileSize = 0;\\n    }\\n\\n    // 获取创建时间\\n    const dateAdded = asset.get(photoAccessHelper.PhotoKeys.DATE_ADDED) as number;\\n    const createTime = new Date(dateAdded * 1000).toISOString();\\n\\n    // 创建 ImageItem 实例\\n    const imageItem = new ImageItem(\\n      asset.uri,\\n      asset.displayName || `图片_${i + 1}`,\\n      fileSize,\\n      createTime,\\n      thumbnail,\\n      asset\\n    );\\n\\n    imageItems.push(imageItem);\\n  } catch (error) {\\n    console.error(`处理图片失败:`, error);\\n  }\\n}\\n```\\n\\n### 步骤 6：UI 状态管理\\n\\n根据不同状态显示相应的 UI 界面。\\n\\n```typescript\\nbuild() {\\n  Column() {\\n    if (this.localModel.isLoading) {\\n      // 加载状态\\n      Column() {\\n        LoadingProgress()\\n        Text('正在加载图片...')\\n      }\\n    } else if (!this.localModel.hasPermission) {\\n      // 权限提示\\n      Column() {\\n        Image($r('app.media.lightbulb'))\\n        Text('需要访问相册权限')\\n        Button('重新授权')\\n          .onClick(() => {\\n            this.initializeGallery();\\n          })\\n      }\\n    } else if (this.localModel.images.length === 0) {\\n      // 空状态\\n      Column() {\\n        Image($r('app.media.grid_horizontal'))\\n        Text('暂无图片')\\n      }\\n    } else {\\n      // 图片网格\\n      Scroll() {\\n        Grid() {\\n          ForEach(this.localModel.images, (image: ImageItem) => {\\n            GridItem() {\\n              this.buildImageItem(image)\\n            }\\n          })\\n        }\\n        .columnsTemplate('1fr 1fr 1fr')\\n        .rowsGap(12)\\n        .columnsGap(12)\\n      }\\n    }\\n  }\\n}\\n```\\n\\n## 完整代码\\n\\n```typescript\\nimport { dataSharePredicates } from '@kit.ArkData';\\nimport { image } from '@kit.ImageKit';\\nimport { abilityAccessCtrl, common, PermissionRequestResult } from '@kit.AbilityKit';\\nimport { photoAccessHelper } from '@kit.MediaLibraryKit';\\nimport { fileIo as fs } from '@kit.CoreFileKit';\\n\\n// 图片项数据模型\\n@ObservedV2\\nclass ImageItem {\\n  @Trace id: string = '';\\n  @Trace name: string = '';\\n  @Trace size: number = 0;\\n  @Trace createTime: string = '';\\n  @Trace thumbnail: image.PixelMap | null = null;\\n  @Trace photoAsset: photoAccessHelper.PhotoAsset | null = null;\\n\\n  constructor(id: string, name: string, size: number, createTime: string,\\n    thumbnail: image.PixelMap | null = null, photoAsset: photoAccessHelper.PhotoAsset | null = null) {\\n    this.id = id;\\n    this.name = name;\\n    this.size = size;\\n    this.createTime = createTime;\\n    this.thumbnail = thumbnail;\\n    this.photoAsset = photoAsset;\\n  }\\n}\\n\\n// 图片浏览页面数据模型\\n@ObservedV2\\nclass GalleryModel {\\n  @Trace images: ImageItem[] = [];\\n  @Trace filteredImages: ImageItem[] = [];\\n  @Trace isLoading: boolean = false;\\n  @Trace hasPermission: boolean = false;\\n  @Trace isSearchMode: boolean = false;\\n}\\n\\n@Entry\\n@ComponentV2\\nexport struct Page01 {\\n  @Local localModel: GalleryModel = new GalleryModel();\\n  private context: common.UIAbilityContext = getContext(this) as common.UIAbilityContext;\\n  private phAccessHelper: photoAccessHelper.PhotoAccessHelper | null = null;\\n\\n  aboutToAppear() {\\n    this.initializeGallery();\\n    // 初始化过滤后的图片列表\\n    this.localModel.filteredImages = this.localModel.images;\\n  }\\n\\n  // 构建图片网格项\\n  @Builder\\n  buildImageItem(image: ImageItem) {\\n    Stack({ alignContent: Alignment.TopEnd }) {\\n      // 图片缩略图\\n      Column() {\\n        if (image.thumbnail) {\\n          Image(image.thumbnail)\\n            .width('100%')\\n            .height(120)\\n            .objectFit(ImageFit.Cover)\\n            .borderRadius({ topLeft: 8, topRight: 8 })\\n        } else {\\n          Image($r('app.media.startIcon'))\\n            .width('100%')\\n            .height(120)\\n            .objectFit(ImageFit.Cover)\\n            .borderRadius({ topLeft: 8, topRight: 8 })\\n            .backgroundColor('#F0F0F0')\\n        }\\n\\n        // 图片信息\\n        Column() {\\n          Text(image.name)\\n            .fontSize(12)\\n            .fontColor('#333333')\\n            .maxLines(1)\\n            .textOverflow({ overflow: TextOverflow.Ellipsis })\\n            .width('100%')\\n\\n          // 时间和文件大小在同一行\\n          Row() {\\n            Text(this.formatDateTime(image.createTime))\\n              .fontSize(10)\\n              .fontColor('#666666')\\n              .layoutWeight(1)\\n              .maxLines(1)\\n              .textOverflow({ overflow: TextOverflow.Ellipsis })\\n\\n            Text(this.formatFileSize(image.size))\\n              .fontSize(10)\\n              .fontColor('#999999')\\n          }\\n          .width('100%')\\n          .margin({ top: 2 })\\n        }\\n        .alignItems(HorizontalAlign.Start)\\n        .padding(8)\\n        .width('100%')\\n      }\\n      .backgroundColor('#FFFFFF')\\n      .borderRadius(8)\\n      .shadow({\\n        radius: 4,\\n        color: '#1A000000',\\n        offsetX: 0,\\n        offsetY: 2\\n      })\\n    }\\n  }\\n\\n  build() {\\n    Column() {\\n      if (this.localModel.isLoading) {\\n        // 加载状态\\n        Column() {\\n          LoadingProgress()\\n            .width(40)\\n            .height(40)\\n            .color('#2196F3')\\n\\n          Text('正在加载图片...')\\n            .fontSize(14)\\n            .fontColor('#666666')\\n            .margin({ top: 16 })\\n        }\\n        .layoutWeight(1)\\n        .justifyContent(FlexAlign.Center)\\n        .alignItems(HorizontalAlign.Center)\\n      } else if (!this.localModel.hasPermission) {\\n        // 权限提示\\n        Column() {\\n          Image($r('app.media.lightbulb'))\\n            .width(64)\\n            .height(64)\\n            .fillColor('#FFA726')\\n\\n          Text('需要访问相册权限')\\n            .fontSize(18)\\n            .fontWeight(FontWeight.Medium)\\n            .fontColor('#333333')\\n            .margin({ top: 16 })\\n\\n          Text('请在设置中开启相册访问权限，以便浏览和管理您的图片')\\n            .fontSize(14)\\n            .fontColor('#666666')\\n            .textAlign(TextAlign.Center)\\n            .margin({ top: 8, left: 32, right: 32 })\\n\\n          Button('重新授权')\\n            .type(ButtonType.Capsule)\\n            .backgroundColor('#2196F3')\\n            .fontColor('#FFFFFF')\\n            .fontSize(16)\\n            .padding({\\n              left: 24,\\n              right: 24,\\n              top: 12,\\n              bottom: 12\\n            })\\n            .margin({ top: 24 })\\n            .onClick(() => {\\n              this.initializeGallery();\\n            })\\n        }\\n        .layoutWeight(1)\\n        .justifyContent(FlexAlign.Center)\\n        .alignItems(HorizontalAlign.Center)\\n      } else if ((this.localModel.isSearchMode ? this.localModel.filteredImages : this.localModel.images).length === 0) {\\n        // 空状态\\n        Column() {\\n          Image($r(this.localModel.isSearchMode ? 'app.media.search' : 'app.media.grid_horizontal'))\\n            .width(64)\\n            .height(64)\\n            .fillColor('#BDBDBD')\\n\\n          Text(this.localModel.isSearchMode ? '未找到相关图片' : '暂无图片')\\n            .fontSize(18)\\n            .fontWeight(FontWeight.Medium)\\n            .fontColor('#333333')\\n            .margin({ top: 16 })\\n\\n          Text(this.localModel.isSearchMode ? '尝试使用其他关键词搜索' : '您的相册中还没有图片')\\n            .fontSize(14)\\n            .fontColor('#666666')\\n            .margin({ top: 8 })\\n        }\\n        .layoutWeight(1)\\n        .justifyContent(FlexAlign.Center)\\n        .alignItems(HorizontalAlign.Center)\\n      } else {\\n        // 图片网格\\n        Scroll() {\\n          Grid() {\\n            ForEach(this.localModel.isSearchMode ? this.localModel.filteredImages : this.localModel.images,\\n              (image: ImageItem) => {\\n                GridItem() {\\n                  this.buildImageItem(image)\\n                }\\n              })\\n          }\\n          .columnsTemplate('1fr 1fr 1fr')\\n          .rowsGap(12)\\n          .columnsGap(12)\\n          .padding(16)\\n        }\\n        .layoutWeight(1)\\n        .scrollable(ScrollDirection.Vertical)\\n        .scrollBar(BarState.Auto)\\n      }\\n    }\\n    .width('100%')\\n    .height('100%')\\n    .backgroundColor('#F5F5F5')\\n  }\\n\\n  // 格式化时间显示\\n  formatDateTime(dateTimeString: string): string {\\n    try {\\n      const date = new Date(dateTimeString);\\n      const now = new Date();\\n      const diffTime = now.getTime() - date.getTime();\\n      const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));\\n\\n      if (diffDays === 0) {\\n        // 今天\\n        return `今天 ${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;\\n      } else if (diffDays === 1) {\\n        // 昨天\\n        return `昨天 ${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;\\n      } else if (diffDays < 7) {\\n        // 一周内\\n        const weekdays = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];\\n        return `${weekdays[date.getDay()]} ${date.getHours().toString().padStart(2, '0')}:${date.getMinutes()\\n          .toString()\\n          .padStart(2, '0')}`;\\n      } else {\\n        // 超过一周\\n        return `${date.getFullYear()}/${(date.getMonth() + 1).toString().padStart(2, '0')}/${date.getDate()\\n          .toString()\\n          .padStart(2, '0')}`;\\n      }\\n    } catch (error) {\\n      return dateTimeString; // 如果解析失败，返回原始字符串\\n    }\\n  }\\n\\n  // 初始化图库\\n  private async initializeGallery(): Promise<void> {\\n    try {\\n      this.localModel.isLoading = true;\\n\\n      // 请求权限\\n      const hasPermission = await this.requestPermission();\\n      if (!hasPermission) {\\n        console.error('权限被拒绝，无法访问相册');\\n        this.localModel.hasPermission = false;\\n        this.localModel.isLoading = false;\\n        return;\\n      }\\n\\n      this.localModel.hasPermission = true;\\n\\n      // 初始化PhotoAccessHelper\\n      this.phAccessHelper = photoAccessHelper.getPhotoAccessHelper(this.context);\\n\\n      // 加载图片\\n      await this.loadImagesFromAlbum();\\n\\n    } catch (error) {\\n      console.error('初始化图库失败:', error);\\n    } finally {\\n      this.localModel.isLoading = false;\\n    }\\n  }\\n\\n  // 请求相册读取权限\\n  private async requestPermission(): Promise<boolean> {\\n    try {\\n      const atManager = abilityAccessCtrl.createAtManager();\\n      const permission = 'ohos.permission.READ_IMAGEVIDEO';\\n\\n      // 检查权限状态\\n      const grantStatus = await atManager.checkAccessToken(this.context.applicationInfo.accessTokenId, permission);\\n\\n      if (grantStatus === abilityAccessCtrl.GrantStatus.PERMISSION_GRANTED) {\\n        return true;\\n      }\\n\\n      // 请求权限\\n      const requestResult: PermissionRequestResult =\\n        await atManager.requestPermissionsFromUser(this.context, [permission]);\\n\\n      return requestResult.authResults[0] === abilityAccessCtrl.GrantStatus.PERMISSION_GRANTED;\\n\\n    } catch (error) {\\n      console.error('权限请求失败:', error);\\n      return false;\\n    }\\n  }\\n\\n  // 从相册加载图片数据\\n  private async loadImagesFromAlbum(): Promise<void> {\\n    if (!this.phAccessHelper) {\\n      console.error('PhotoAccessHelper未初始化');\\n      return;\\n    }\\n\\n    try {\\n      // 创建获取选项\\n      const fetchOptions: photoAccessHelper.FetchOptions = {\\n        fetchColumns: [\\n          photoAccessHelper.PhotoKeys.URI,\\n          photoAccessHelper.PhotoKeys.DISPLAY_NAME,\\n          photoAccessHelper.PhotoKeys.SIZE,\\n          photoAccessHelper.PhotoKeys.DATE_ADDED\\n        ],\\n        predicates: new dataSharePredicates.DataSharePredicates()\\n      };\\n\\n      // 按时间倒序排列\\n      fetchOptions.predicates?.orderByDesc(photoAccessHelper.PhotoKeys.DATE_ADDED);\\n\\n      // 获取图片资源\\n      const fetchResult = await this.phAccessHelper.getAssets(fetchOptions);\\n      const photoAssets = await fetchResult.getAllObjects();\\n\\n      // 转换为ImageItem数组\\n      const imageItems: ImageItem[] = [];\\n\\n      for (let i = 0; i < Math.min(photoAssets.length, 50); i++) {\\n        const asset = photoAssets[i];\\n        try {\\n          // 获取缩略图\\n          const thumbnail = await asset.getThumbnail({ width: 300, height: 300 });\\n\\n          // 获取文件大小\\n          let fileSize = 0;\\n          try {\\n            const file = fs.openSync(asset.uri, fs.OpenMode.READ_ONLY);\\n            const stat = await fs.stat(file.fd);\\n            fileSize = stat.size;\\n            fs.closeSync(file.fd);\\n          } catch (sizeError) {\\n            console.error(`获取文件大小失败 ${asset.displayName}:`, sizeError);\\n            fileSize = 0;\\n          }\\n\\n          // 获取图片的真实创建时间\\n          const dateAdded = asset.get(photoAccessHelper.PhotoKeys.DATE_ADDED) as number;\\n          const createTime = new Date(dateAdded * 1000).toISOString();\\n\\n          const imageItem = new ImageItem(\\n            asset.uri,\\n            asset.displayName || `图片_${i + 1}`,\\n            fileSize,\\n            createTime,\\n            thumbnail,\\n            asset\\n          );\\n\\n          imageItems.push(imageItem);\\n        } catch (thumbnailError) {\\n          console.error(`获取缩略图失败 ${asset.displayName}:`, thumbnailError);\\n\\n          // 即使缩略图获取失败，也尝试获取文件大小\\n          let fileSize = 0;\\n          try {\\n            const file = fs.openSync(asset.uri, fs.OpenMode.READ_ONLY);\\n            const stat = await fs.stat(file.fd);\\n            fileSize = stat.size;\\n            fs.closeSync(file.fd);\\n          } catch (sizeError) {\\n            console.error(`获取文件大小失败 ${asset.displayName}:`, sizeError);\\n            fileSize = 0;\\n          }\\n\\n          // 获取图片的真实创建时间\\n          const dateAdded = asset.get(photoAccessHelper.PhotoKeys.DATE_ADDED) as number;\\n          const createTime = new Date(dateAdded * 1000).toISOString();\\n\\n          const imageItem = new ImageItem(\\n            asset.uri,\\n            asset.displayName || `图片_${i + 1}`,\\n            fileSize,\\n            createTime,\\n            null,\\n            asset\\n          );\\n          imageItems.push(imageItem);\\n        }\\n      }\\n\\n      this.localModel.images = imageItems;\\n      this.localModel.filteredImages = imageItems;\\n      console.info(`成功加载 ${imageItems.length} 张图片`);\\n\\n      // 关闭fetchResult\\n      fetchResult.close();\\n\\n    } catch (error) {\\n      console.error('加载相册图片失败:', error);\\n      // 如果加载失败，显示空状态\\n      this.localModel.images = [];\\n      this.localModel.filteredImages = [];\\n    }\\n  }\\n\\n  // 格式化文件大小\\n  private formatFileSize(bytes: number): string {\\n    if (bytes === 0) {\\n      return '0 B';\\n    }\\n    const k = 1024;\\n    const sizes = ['B', 'KB', 'MB', 'GB'];\\n    const i = Math.floor(Math.log(bytes) / Math.log(k));\\n    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];\\n  }\\n}\\n```\\n\\n\\n\\n\\n\\n## 关键技术要点\\n\\n### 1. 权限管理\\n- 必须在 `module.json5` 中声明权限\\n- 运行时动态申请权限\\n- 处理权限被拒绝的情况\\n\\n### 2. 性能优化\\n- 限制加载图片数量（示例中限制为50张）\\n- 使用缩略图而非原图显示\\n- 异步加载，避免阻塞 UI 线程\\n\\n### 3. 错误处理\\n- 权限申请失败处理\\n- 图片加载失败的降级方案\\n- 文件访问异常的容错机制\\n\\n### 4. 状态管理\\n- 使用 V2 状态管理架构\\n- 响应式数据更新\\n- 组件状态与数据模型分离\\n\\n## 总结\\n\\n通过以上步骤，我们成功实现了 HarmonyOS 应用中读取相册图片并预览的功能。该实现方案具有以下特点：\\n\\n1. **安全性**：严格的权限管理机制\\n2. **性能**：优化的图片加载和显示策略\\n3. **用户体验**：完善的加载状态和错误提示\\n4. **可维护性**：清晰的代码结构和状态管理\\n\\n这个实现为开发者提供了一个完整的相册访问解决方案，可以作为类似功能开发的参考模板。\\n\\n## 关于我们\\n\\n[关于青蓝逐码组织](https://www.qinglanzhuma.cn/)\\n\\n如果你兴趣想要了解更多的鸿**蒙应用开发细节和最新资讯**，**甚至你想要做出一款属于自己的应用**！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n![image-20250622200325374](assets/image-20250622200325374.png)\\n\\n---\\n\\n我们目前已经孵化了6个上架的鸿蒙作品\\n\\n![image-20250804212748706](assets/image-20250804212748706.png)\"}"),r={name:"鸿蒙开发技巧/HarmonyOS 读取系统相册图片并预览/HarmonyOS 读取系统相册图片并预览.md"};function E(d,s,g,y,c,F){return a(),n("div",null,[...s[0]||(s[0]=[l("",80)])])}const m=i(r,[["render",E]]);export{b as __pageData,m as default};
